import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api';
import { useAuth } from '../context/AuthContext';
import DoctorCard from '../components/DoctorCard';

export default function Doctors() {
  const [doctors, setDoctors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  const [msg, setMsg] = useState({ text: '', type: '' });
  const { auth } = useAuth();
  const navigate = useNavigate();
  const isDoctor = auth.user.role === 'doctor';

  const load = () => {
    setLoading(true);
    api.get('/doctors')
      .then(r => setDoctors(r.data))
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, []);

  const book = async (doctorId) => {
    if (!date || !time) return setMsg({ text: 'Please select a date and time before booking.', type: 'error' });
    try {
      await api.post('/appointments', { doctor: doctorId, date, time });
      setMsg({ text: 'Appointment booked successfully!', type: 'success' });
      setTimeout(() => setMsg({ text: '', type: '' }), 3000);
    } catch (err) {
      setMsg({ text: err.response?.data?.message || 'Booking failed.', type: 'error' });
    }
  };

  const openChat = (doctorId) => {
    const roomId = [auth.user.id, doctorId].sort().join('_');
    navigate(`/chat/${roomId}`);
  };

  const toggleAvailability = async () => {
    try {
      const { data } = await api.patch('/doctors/availability');
      setDoctors(prev => prev.map(d =>
        d._id === auth.user.id ? { ...d, isAvailable: data.isAvailable } : d
      ));
    } catch {
      setMsg({ text: 'Failed to update availability.', type: 'error' });
    }
  };

  // For doctor view: find their own card
  const myCard = isDoctor ? doctors.find(d => d._id === auth.user.id) : null;

  return (
    <div className="mt-8 max-w-5xl mx-auto">
      <div className="mb-6">
        <h2 className="text-2xl font-bold text-gray-800">
          {isDoctor ? 'My Profile' : 'Find a Doctor'}
        </h2>
        <p className="text-gray-500 text-sm mt-1">
          {isDoctor ? 'Manage your availability' : 'Browse available specialists and book an appointment'}
        </p>
      </div>

      {/* Doctor's own availability toggle */}
      {isDoctor && myCard && (
        <div className="max-w-sm">
          <DoctorCard
            doctor={myCard}
            showToggle
            onToggle={toggleAvailability}
          />
        </div>
      )}

      {/* Patient view */}
      {!isDoctor && (
        <>
          {/* Date/Time picker */}
          <div className="bg-white border border-gray-100 rounded-2xl p-4 shadow-sm mb-6 flex flex-wrap gap-4 items-end">
            <div className="flex flex-col gap-1">
              <label className="text-xs font-medium text-gray-500 uppercase tracking-wide">Date</label>
              <input type="date" className="input w-44" value={date} onChange={e => setDate(e.target.value)} />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs font-medium text-gray-500 uppercase tracking-wide">Time</label>
              <input type="time" className="input w-36" value={time} onChange={e => setTime(e.target.value)} />
            </div>
            {msg.text && (
              <p className={`text-sm font-medium ${msg.type === 'success' ? 'text-green-600' : 'text-red-500'}`}>
                {msg.text}
              </p>
            )}
          </div>

          {/* Loading */}
          {loading && (
            <div className="text-center py-16 text-gray-400">
              <p className="text-4xl mb-3 animate-pulse">🏥</p>
              <p className="text-sm">Loading doctors...</p>
            </div>
          )}

          {/* Empty state */}
          {!loading && doctors.length === 0 && (
            <div className="text-center py-16 bg-white border border-gray-100 rounded-2xl shadow-sm">
              <p className="text-5xl mb-4">👨‍⚕️</p>
              <p className="text-gray-700 font-semibold text-lg">No doctors available</p>
              <p className="text-gray-400 text-sm mt-1">Please check back later or contact support.</p>
            </div>
          )}

          {/* Doctor grid */}
          {!loading && doctors.length > 0 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
              {doctors.map(doc => (
                <DoctorCard
                  key={doc._id}
                  doctor={doc}
                  onBook={book}
                  onChat={openChat}
                />
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
}
